# Let me look for possible base transformations by checking what characters get replaced with what
inputs = ['jwc', 'jajzgh', 'kxuge', 'cijefx', 'vkvi']
outputs = ['jwdi', 'jhexjzgh', 'ddwxuge', 'diijefx', 'vddwvi']

# Try to identify patterns by looking at character mappings
print("Character-by-character analysis:")

# Check what characters map to what
mapping = {}
for inp, out in zip(inputs, outputs):
    min_len = min(len(inp), len(out))
    for i in range(min_len):
        if inp[i] not in mapping:
            mapping[inp[i]] = set()
        mapping[inp[i]].add(out[i])

print("Character mappings (input -> possible outputs):")
for char, targets in mapping.items():
    print(f"  '{char}' -> {list(targets)}")

# Look for consistent single character replacements
print("\nConsistent single character replacements:")
single_replacements = {}
for inp, out in zip(inputs, outputs):
    min_len = min(len(inp), len(out))
    for i in range(min_len):
        if inp[i] != out[i]:
            if inp[i] not in single_replacements:
                single_replacements[inp[i]] = out[i]
            elif single_replacements[inp[i]] != out[i]:
                # Multiple different mappings - not consistent
                pass

for char, target in single_replacements.items():
    print(f"  '{char}' -> '{target}'")

